sketch.css:
.fm{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:10px 12px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden;container-type:inline-size}
.fm *{box-sizing:border-box}
.head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.title{font-weight:600}
.unit{color:var(--muted);font-size:11.5px;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.modes{display:flex;gap:2px;background:var(--background);border-radius:8px;padding:2px}
.mode{padding:2px 10px;border-radius:6px;font-size:11.5px;font-weight:500;color:var(--muted);cursor:pointer}
.mode:hover{color:var(--text)}
.mode.selected{background:var(--window);color:var(--accent);box-shadow:0 1px 2px rgba(20,20,50,.1)}
.matrix{flex:1;min-height:0;display:flex;flex-direction:column;border-top:1px solid var(--border)}
.mhead,.lane{display:grid;grid-template-columns:minmax(96px,1.5fr) repeat(var(--n),minmax(0,1fr));gap:8px;align-items:center}
.mhead{padding:6px 6px 4px;font-size:11.5px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.03em}
.mhead .mc{text-align:center}
.lanes{flex:1;overflow:auto}
.lane{padding:5px 6px;border-bottom:1px solid var(--border);border-radius:6px;cursor:pointer}
.lane:hover{background:var(--hover)}
.lane.selected{background:var(--hover);box-shadow:inset 3px 0 0 var(--accent)}
.lname{min-width:0}
.lname b{display:block;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lname span{display:block;color:var(--muted);font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cell{position:relative;text-align:center;padding:3px 4px;border-radius:7px;border:1px solid transparent;min-width:0}
.cell .rate{font-weight:600;font-variant-numeric:tabular-nums;line-height:1.25}
.cell .sub{display:flex;justify-content:center;gap:5px;font-size:11px;color:var(--muted);white-space:nowrap}
.cell .up{color:var(--red);font-weight:600}
.cell .down{color:var(--green);font-weight:600}
.cell.na{color:var(--muted);opacity:.6;padding:8px 4px}
.cell.best{background:color-mix(in srgb,var(--green) 13%,transparent);border-color:color-mix(in srgb,var(--green) 55%,transparent)}
.cell.best .rate{color:var(--green)}
.cell.best::after{content:"";position:absolute;top:4px;right:4px;width:6px;height:6px;border-radius:50%;background:var(--green)}
.empty{color:var(--muted);text-align:center;padding:24px 0}
.demurrage{border-top:1px solid var(--border);padding-top:6px}
.dtitle{display:flex;justify-content:space-between;font-size:11.5px;color:var(--muted);margin-bottom:5px}
.dtitle b{color:var(--text);font-weight:600}
.buckets{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.bucket{border-radius:8px;padding:5px 8px;background:color-mix(in srgb,var(--red) calc(var(--t) * 1%),var(--background));border:1px solid color-mix(in srgb,var(--red) calc(var(--t) * 1%),var(--border));min-width:0}
.bucket .bl{font-size:11px;font-weight:600;color:var(--muted)}
.bucket .bv{font-size:15px;font-weight:700;line-height:1.2;letter-spacing:-.01em}
.bucket .bs{font-size:11px;color:var(--muted);white-space:nowrap}
.bucket.hot .bv,.bucket.hot .bs{color:var(--red)}
@container (max-width:480px){
  .unit{display:none}
  .fm{padding:8px 8px;gap:6px}
  .mhead,.lane{gap:4px}
  .cell .sub{flex-direction:column;gap:0;align-items:center}
  .bucket .bv{font-size:13px}
  .bucket{padding:4px 6px}
}

sketch.js:
function render(root, props, fire) {
  const MODES = [{ k: 'all', t: 'All' }, { k: 'rail', t: 'Rail' }, { k: 'truck', t: 'Truck' }, { k: 'barge', t: 'Barge' }];
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const lanes = props.lanes || [];
  const dem = props.demurrage || [];
  const mode = MODES.some(m => m.k === props.mode) ? props.mode : 'all';
  const cols = mode === 'all' ? ['rail', 'truck', 'barge'] : [mode];
  const name = k => k.charAt(0).toUpperCase() + k.slice(1);
  const money = v => '$' + (v >= 10000 ? (v / 1000).toFixed(1).replace(/\.0$/, '') + 'k' : Math.round(v).toLocaleString());

  const md = root.querySelector('.modes');
  md.innerHTML = MODES.map(m => '<span class="mode' + (m.k === mode ? ' selected' : '') + '" data-m="' + m.k + '">' + m.t + '</span>').join('');
  md.querySelectorAll('.mode').forEach(el => el.onclick = () => fire('modeChanged', { mode: el.dataset.m }));

  const head = root.querySelector('.mhead');
  head.style.setProperty('--n', cols.length);
  head.innerHTML = '<span>Lane</span>' + cols.map(c => '<span class="mc">' + name(c) + '</span>').join('');

  const list = root.querySelector('.lanes');
  if (!lanes.length) list.innerHTML = '<div class="empty">No lanes</div>';
  else list.innerHTML = lanes.map(l => {
    const all = ['rail', 'truck', 'barge'].map(c => ({ c, r: +l[c + 'Rate'] || 0 })).filter(x => x.r > 0);
    const best = all.length ? all.reduce((a, b) => b.r < a.r ? b : a).c : '';
    return '<div class="lane' + (l.lane === props.selected ? ' selected' : '') + '" data-lane="' + esc(l.lane) + '" style="--n:' + cols.length + '">' +
      '<div class="lname"><b>' + esc(l.origin) + ' → ' + esc(l.destination) + '</b></div>' +
      cols.map(c => {
        const r = +l[c + 'Rate'] || 0;
        if (r <= 0) return '<div class="cell na"><div class="rate">—</div></div>';
        const d = +l[c + 'Days'] || 0, t = +l[c + 'Trend'] || 0;
        const tr = Math.abs(t) < 0.05 ? '<span>–</span>' : '<span class="' + (t > 0 ? 'up' : 'down') + '">' + (t > 0 ? '▲' : '▼') + Math.abs(t).toFixed(1) + '%</span>';
        return '<div class="cell' + (c === best ? ' best' : '') + '" title="' + name(c) + (c === best ? ' · cheapest' : '') + '"><div class="rate">$' + r.toFixed(3) + '</div><div class="sub"><span>' + d + 'd</span>' + tr + '</div></div>';
      }).join('') + '</div>';
  }).join('');
  list.querySelectorAll('.lane').forEach(el => el.onclick = () => fire('laneSelected', { lane: el.dataset.lane, selected: el.dataset.lane }));

  const cars = dem.reduce((a, b) => a + (+b.cars || 0), 0), amt = dem.reduce((a, b) => a + (+b.amount || 0), 0);
  root.querySelector('.dtitle').innerHTML = '<span>Demurrage aging</span><span><b>' + cars + '</b> cars · <b>' + money(amt) + '</b> accrued</span>';
  root.querySelector('.buckets').innerHTML = dem.map((b, i) => {
    const t = dem.length > 1 ? Math.round(i / (dem.length - 1) * 45) : 0;
    return '<div class="bucket' + (i >= dem.length - 2 ? ' hot' : '') + '" style="--t:' + t + '"><div class="bl">' + esc(b.bucket) + ' days</div><div class="bv">' + (+b.cars || 0) + ' cars</div><div class="bs">' + money(+b.amount || 0) + '</div></div>';
  }).join('');
}
